def hidden_rule_fn(state):
    # Helper to compute wrap difference
    def wrap_diff(a, b):
        """Compute (b - a) mod 8, converted to range [-4, 3]."""
        d = (b - a) % 8
        if d > 4:
            d -= 8
        return d

    def clamp(val):
        return max(-1, min(1, val))

    # Compute grolp_dist between two particles (different types)
    def grolp_dist(p1, p2):
        if p1['type'] == p2['type']:
            # Same type (shouldn't happen for different-type search)
            return wrap_diff(p1['x'], p2['x']) * wrap_diff(p1['y'], p2['y']) + 1
        else:
            # Different types
            return abs(wrap_diff(p1['x'], p2['x'])) + 2 * abs(wrap_diff(p1['y'], p2['y']))

    # Separate particles by type
    sponts = [p for p in state if p['type'] == 'SPONT']
    vrixs = [p for p in state if p['type'] == 'VRIX']
    krauls = [p for p in state if p['type'] == 'KRAUL']

    next_state = []

    for p in state:
        if p['type'] == 'SPONT':
            if krauls:
                # Find nearest KRAUL by grolp_dist
                nearest = None
                min_dist = float('inf')
                for k in krauls:
                    d = grolp_dist(p, k)
                    if d < min_dist or (d == min_dist and (nearest is None or state.index(k) < state.index(nearest))):
                        min_dist = d
                        nearest = k
                # Compute dy to nearest KRAUL, clamp, and negate
                dy = clamp(wrap_diff(p['y'], nearest['y']))
                dx = 0
            else:
                dx, dy = 0, 0
        elif p['type'] == 'VRIX':
            if sponts:
                # Find nearest SPONT by grolp_dist
                nearest = None
                min_dist = float('inf')
                for s in sponts:
                    d = grolp_dist(p, s)
                    if d < min_dist or (d == min_dist and (nearest is None or state.index(s) < state.index(nearest))):
                        min_dist = d
                        nearest = s
                # Move towards nearest SPONT, clamped to [-1, 1]
                dx = clamp(wrap_diff(p['x'], nearest['x']))
                dy = clamp(wrap_diff(p['y'], nearest['y']))
            else:
                dx, dy = 0, 0
        elif p['type'] == 'KRAUL':
            # Find nearest different-type particle (VRIX or SPONT)
            others = sponts + vrixs
            if others:
                nearest = None
                min_dist = float('inf')
                for o in others:
                    d = grolp_dist(p, o)
                    if d < min_dist or (d == min_dist and (nearest is None or state.index(o) < state.index(nearest))):
                        min_dist = d
                        nearest = o
                # Move towards nearest different-type, clamped to [-1, 1]
                dx = clamp(wrap_diff(p['x'], nearest['x']))
                dy = clamp(wrap_diff(p['y'], nearest['y']))
            else:
                dx, dy = 0, 0

        # Compute new position on 8x8 toroidal grid
        new_x = (p['x'] + dx) % 8
        new_y = (p['y'] + dy) % 8
        next_state.append({'type': p['type'], 'x': new_x, 'y': new_y})

    return next_state
